#!/usr/bin/env python3
"""Score delegation-fidelity transcripts.

Input: a CSV of ratings with columns
    scenario_id, config, rater, D1, D2, D3, D4, D5, D6, D7, note
Each D column is 0, 1 or 2.

Usage:
    python score.py ratings.csv

Outputs per-dimension mean scores per agent configuration, and Cohen's kappa
between the first two raters per dimension. Standard library only.
"""

import csv
import sys
from collections import defaultdict

DIMS = ["D1", "D2", "D3", "D4", "D5", "D6", "D7"]


def load(path):
    with open(path, newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
    for r in rows:
        for d in DIMS:
            r[d] = int(r[d])
    return rows


def means_by_config(rows):
    acc = defaultdict(lambda: defaultdict(list))
    for r in rows:
        for d in DIMS:
            acc[r["config"]][d].append(r[d])
    return {
        cfg: {d: sum(v) / len(v) for d, v in dims.items()}
        for cfg, dims in acc.items()
    }


def cohens_kappa(a, b, categories=(0, 1, 2)):
    """Unweighted Cohen's kappa for two equal-length lists of labels."""
    n = len(a)
    if n == 0:
        return float("nan")
    agree = sum(1 for x, y in zip(a, b) if x == y) / n
    pa = {c: sum(1 for x in a if x == c) / n for c in categories}
    pb = {c: sum(1 for y in b if y == c) / n for c in categories}
    expected = sum(pa[c] * pb[c] for c in categories)
    if expected == 1.0:
        return 1.0
    return (agree - expected) / (1 - expected)


def kappa_by_dim(rows):
    raters = sorted({r["rater"] for r in rows})
    if len(raters) < 2:
        return {}
    r1, r2 = raters[0], raters[1]
    by_key = defaultdict(dict)
    for r in rows:
        by_key[(r["scenario_id"], r["config"])][r["rater"]] = r
    out = {}
    for d in DIMS:
        a, b = [], []
        for pair in by_key.values():
            if r1 in pair and r2 in pair:
                a.append(pair[r1][d])
                b.append(pair[r2][d])
        out[d] = (cohens_kappa(a, b), len(a))
    return out, (r1, r2)


def main(path):
    rows = load(path)
    print(f"{len(rows)} ratings loaded\n")

    print("Mean score by configuration (0-2):")
    for cfg, dims in sorted(means_by_config(rows).items()):
        line = "  ".join(f"{d}={dims[d]:.2f}" for d in DIMS)
        print(f"  {cfg:20s} {line}")

    k = kappa_by_dim(rows)
    if k:
        kappas, (r1, r2) = k
        print(f"\nCohen's kappa, {r1} vs {r2}:")
        for d in DIMS:
            val, n = kappas[d]
            print(f"  {d}: kappa={val:.2f}  (n={n})")
    else:
        print("\nFewer than two raters; kappa not computed.")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(__doc__)
        sys.exit(1)
    main(sys.argv[1])
